namespace EsoAddons.Services;

/// <summary>Runtime UI localization. Bind labels via the {loc:Tr Key} markup extension; switching
/// <see cref="Lang"/> updates every bound string live (no restart) by re-raising the indexer. Only the
/// app's own chrome is translated — add-on names/descriptions from ESOUI and AI results stay in their
/// source language. This is the CORE-UI slice; more strings get added over time.</summary>
public sealed class Loc : INotifyPropertyChanged
{
    public static Loc Instance { get; } = new();

    /// <summary>Supported languages: code + native display name (shown in the picker).</summary>
    public static readonly (string Code, string Name)[] Languages =
    {
        ("en", "English"), ("es", "Español"), ("de", "Deutsch"), ("fr", "Français"), ("pt", "Português"),
    };

    private string _lang = "en";
    public string Lang
    {
        get => _lang;
        set
        {
            var v = string.IsNullOrWhiteSpace(value) || !_t.ContainsKey(value) ? "en" : value;
            if (_lang == v) return;
            _lang = v;
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs("Item[]")); // refresh all indexer bindings
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(Lang)));
        }
    }

    /// <summary>Localized string for a key (XAML indexer binding target). Falls back to English, then the key.</summary>
    public string this[string key] => Get(_lang, key);

    public static bool Supported(string lang) => _t.ContainsKey(lang);

    public static string Get(string lang, string key) =>
        _t.TryGetValue(lang, out var d) && d.TryGetValue(key, out var v) ? v
        : _t["en"].TryGetValue(key, out var e) ? e : key;

    public event PropertyChangedEventHandler? PropertyChanged;

