            ["Nav_Next"] = "Siguiente ▶", ["Nav_Done"] = "Listo", ["Nav_Back"] = "Atrás", ["Nav_Skip"] = "Omitir tutorial",
            ["Walk_WelcomeTitle"] = "Bienvenido a Shoyru's Addon Suite",
            ["Walk_WelcomeBody"] = "Tu gestor de add-ons todo en uno para The Elder Scrolls Online. Aquí tienes un recorrido rápido por lo que puede hacer — puedes omitirlo cuando quieras.",
            ["Walk_InstalledTitle"] = "Tus add-ons instalados",
            ["Walk_InstalledBody"] = "La pestaña Instalados muestra todo lo que tienes. Búscalo, ordena cualquier columna — incluidas versión y fecha de publicación — y elimina lo que ya no quieras.",
            ["Walk_BrowseTitle"] = "Explora todo ESOUI",
            ["Walk_BrowseBody"] = "Cambia a Explorar para buscar en todo el catálogo de ESOUI e instalar cualquier add-on con un solo clic. Filtra por categoría u ordena por descargas y fecha de publicación.",
            ["Walk_DescribeTitle"] = "✨ O simplemente descríbelo",
            ["Walk_DescribeBody_Pro"] = "¿No sabes el nombre del add-on? Solo describe lo que quieres. Mira aquí — escribimos «muéstrame alertas de habilidades» y aparecieron los add-ons que coinciden, ordenados por lo bien que encajan. Para hacerlo tú: escribe una descripción y pulsa ✨ Describir.",
            ["Walk_DescribeBody_Free"] = "¿No sabes el nombre del add-on? Con Pro, solo describe lo que quieres y la IA encuentra add-ons que coinciden. Mira aquí — escribimos «muéstrame alertas de habilidades» y aparecieron estos. Es una función Pro — desbloquéala desde el botón ✨ Describir (Pro).",
            ["Walk_DetailsTitle"] = "Detalles y dependencias",
            ["Walk_DetailsBody"] = "Haz clic en cualquier add-on para leer su descripción y su registro de cambios y ver las bibliotecas que necesita — con un clic para instalar las que falten.",
            ["Walk_TranslateTitle"] = "🌐 Lee los add-ons en tu idioma",
            ["Walk_TranslateBody_Pro"] = "Las descripciones de los add-ons las escriben sus autores, normalmente en inglés. Abre cualquier add-on y pulsa 🌐 Traducir en su descripción para leerla en tu idioma; vuelve cuando quieras con «Ver original».",
            ["Walk_TranslateBody_Free"] = "Las descripciones de los add-ons las escriben sus autores, normalmente en inglés. Con Pro, un clic traduce cualquier descripción a tu idioma. Es una función Pro — desbloquéala con Pro.",
            ["Walk_ProTitle_Pro"] = "Herramientas Pro",
            ["Walk_ProTitle_Free"] = "Haz aún más con Pro",
            ["Walk_ProBody_Pro"] = "Las Herramientas Pro son tu centro de control — perfiles y configuraciones, copias de seguridad y sincronización entre PC, además de actualizaciones automáticas que mantienen todo al día por ti.",
            ["Walk_ProBody_Free"] = "Pro añade actualización automática al abrir, temas claro y oscuro, categorías de add-ons, instalación automática de dependencias, y perfiles, copias de seguridad y sincronización entre PC. Actualizar todo y tus add-ons siempre son gratis — Pro solo hace que el gestor sea sin esfuerzo.",
            ["Walk_SetTitle"] = "¡Todo listo!",
            ["Walk_SetBody"] = "Si tu carpeta de AddOns no se encontró automáticamente, defínela con «Cambiar carpeta de AddOns…» en el menú ⚙ — también puedes repetir este tutorial desde ahí cuando quieras. ¡Feliz modding!",
            ["Tour_WelcomeTitle"] = "🎉 ¡Bienvenido a Pro!",
            ["Tour_WelcomeBody"] = "Gracias por apoyar Shoyru's Addon Suite. Aquí tienes un recorrido rápido por todo lo que acabas de desbloquear.",
            ["Tour_DescribeTitle"] = "✨ Describir — tu nuevo buscador de add-ons con IA",
            ["Tour_DescribeBody"] = "Describe lo que quieres con tus palabras y la IA encuentra add-ons que coinciden, ordenados por relevancia. Mira aquí — escribimos «muéstrame alertas de habilidades» y aparecieron estos. Para usarlo: escribe una descripción y pulsa ✨ Describir.",
            ["Tour_TranslateTitle"] = "🌐 Traduce las descripciones de add-ons",
            ["Tour_TranslateBody"] = "Las descripciones de los add-ons las escriben sus autores, normalmente en inglés. Abre cualquier add-on y pulsa 🌐 Traducir en su descripción para leerla en tu idioma — vuelve con «Ver original».",
            ["Tour_UpdateTitle"] = "Actualizar todo con un clic",
            ["Tour_UpdateBody"] = "Actualiza todos los add-ons a la vez — y activa la actualización automática al abrir (en Herramientas Pro) para que se mantengan al día sin que muevas un dedo.",
            ["Tour_ToolsTitle"] = "Herramientas Pro",
            ["Tour_ToolsBody"] = "Tu centro de control: guarda perfiles y configuraciones, haz copias de seguridad de todo y sincroniza tu configuración entre varios PC.",
            ["Tour_CatTitle"] = "Organiza con categorías",
            ["Tour_CatBody"] = "Tus add-ons instalados ahora muestran una Categoría — rellenada automáticamente desde ESOUI y totalmente editable. Haz clic en el encabezado de la columna Categoría para agruparlos.",
            ["Tour_DepsTitle"] = "Dependencias automáticas",
            ["Tour_DepsBody"] = "Instala cualquier add-on y Pro añade automáticamente las bibliotecas que necesita — se acabaron los errores de «falta una dependencia» en el juego.",
            ["Tour_ThemeTitle"] = "Temas claro y oscuro",
            ["Tour_ThemeBody"] = "Hazlo tuyo — cambia entre el tema claro y el oscuro cuando quieras desde el menú ⚙.",
            ["Tour_EnjoyTitle"] = "¡Disfruta de Pro!",
            ["Tour_EnjoyBody"] = "Eso es todo. Tus add-ons siempre son gratis — Pro solo hace que gestionarlos sea sin esfuerzo. ¡Gracias de nuevo por tu apoyo! 💙",
            ["Spot_318_Summary"] = "Herramientas Pro — perfiles, copias, sincronización entre PC y actualización automática",
            ["Spot_318_Title"] = "Herramientas Pro",
            ["Spot_318_Body"] = "Los perfiles/configuraciones, las copias de seguridad, la sincronización entre PC y la actualización automática al abrir están todos aquí (Pro).",
            ["Spot_320_Summary"] = "Categorías de add-ons + una fecha «Publicado» ordenable",
            ["Spot_320_Title"] = "Categorías y fecha «Publicado»",
            ["Spot_320_Body"] = "Los add-ons instalados ahora muestran una Categoría (rellenada automáticamente desde ESOUI y modificable) más una fecha «Publicado» ordenable. Haz clic en cualquier encabezado para ordenar.",
            ["Spot_322_Summary"] = "Tutorial de primera vez + repetición",
            ["Spot_322_Title"] = "Repítelo cuando quieras",
            ["Spot_322_Body"] = "Repite este tutorial de bienvenida cuando quieras — está en el menú ⚙ de ajustes, arriba a la derecha.",
            ["Spot_44_Summary"] = "Encabezado más limpio — acciones secundarias movidas a ⚙",
