            ["Walk_ProBody_Free"] = "Pro bringt Auto-Update beim Start, helle und dunkle Designs, Add-on-Kategorien, automatische Abhängigkeitsinstallation sowie Profile, Backups & Multi-PC-Sync. Alle aktualisieren und deine Add-ons bleiben immer kostenlos — Pro macht den Manager nur mühelos.",
            ["Walk_SetTitle"] = "Alles bereit",
            ["Walk_SetBody"] = "Falls dein AddOns-Ordner nicht automatisch gefunden wurde, lege ihn über „AddOns-Ordner ändern…“ im ⚙-Menü fest — von dort kannst du diese Tour auch jederzeit wiederholen. Viel Spaß beim Modden!",
            ["Tour_WelcomeTitle"] = "🎉 Willkommen bei Pro!",
            ["Tour_WelcomeBody"] = "Danke, dass du Shoyru's Addon Suite unterstützt. Hier ist eine kurze Tour durch alles, was du gerade freigeschaltet hast.",
            ["Tour_DescribeTitle"] = "✨ Beschreiben — dein neuer KI-Add-on-Finder",
            ["Tour_DescribeBody"] = "Beschreibe in einfachen Worten, was du suchst, und die KI findet passende Add-ons, nach Relevanz sortiert. Sieh hier — wir tippten „zeig mir Hinweise für Fähigkeiten“ und diese erschienen. So nutzt du es: Beschreibung eingeben, dann ✨ Beschreiben klicken.",
            ["Tour_TranslateTitle"] = "🌐 Add-on-Beschreibungen übersetzen",
            ["Tour_TranslateBody"] = "Add-on-Beschreibungen werden von ihren Autoren verfasst, meist auf Englisch. Öffne ein Add-on und klicke bei seiner Beschreibung auf 🌐 Übersetzen, um sie in deiner Sprache zu lesen — mit „Original anzeigen“ wechselst du zurück.",
            ["Tour_UpdateTitle"] = "Alle aktualisieren mit einem Klick",
            ["Tour_UpdateBody"] = "Aktualisiere alle Add-ons auf einmal — und schalte Auto-Update beim Start (in den Pro-Tools) ein, damit sie aktuell bleiben, ohne dass du einen Finger rührst.",
            ["Tour_ToolsTitle"] = "Pro-Tools",
            ["Tour_ToolsBody"] = "Deine Schaltzentrale: Profile und Loadouts speichern, alles sichern und dein Setup über mehrere PCs synchronisieren.",
            ["Tour_CatTitle"] = "Mit Kategorien organisieren",
            ["Tour_CatBody"] = "Deine installierten Add-ons zeigen jetzt eine Kategorie — automatisch von ESOUI ausgefüllt und voll bearbeitbar. Klicke auf die Spaltenüberschrift „Kategorie“, um sie zu gruppieren.",
            ["Tour_DepsTitle"] = "Automatische Abhängigkeiten",
            ["Tour_DepsBody"] = "Installiere ein Add-on und Pro holt automatisch die benötigten Bibliotheken — keine „fehlende Abhängigkeit“-Fehler mehr im Spiel.",
            ["Tour_ThemeTitle"] = "Helle & dunkle Designs",
            ["Tour_ThemeBody"] = "Mach es zu deinem — wechsle jederzeit über das ⚙-Menü zwischen hellem und dunklem Design.",
            ["Tour_EnjoyTitle"] = "Viel Spaß mit Pro!",
